# -*- coding: utf-8 -*-
TIER2_HEAD = r'<b>【 แบบที่ 2 ▸ พื้นฐาน · กระชับ · กฎของไซน์คู่กับสูตรมุมสองเท่าเพื่อหา $\cos C$ (law of sines with the double-angle formula) 】</b>'
TIER2 = [
    r'🎯 <b>เหมาะกับ</b> เด็กปานกลางถึงเก่ง · ใช้กฎไซน์กับกฎโคไซน์คล่องแล้ว และรู้ว่าเงื่อนไขที่ยังไม่ได้ใช้คือเครื่องมือคัดราก',
    r'<b>ขั้นที่ 1:</b> กฎไซน์คู่ $b$ กับ $c$ คูณไขว้ได้ $b\sin C = c\sin B$ แทน $b = 12$ , $c = 9$ , $B = 2C$ แล้วกางด้วย $\sin 2C = 2\sin C\cos C$',
    r'⇒ $12\sin C = 9\left(2\sin C\cos C\right) = 18\sin C\cos C$ ⇒ $C$ เป็นมุมภายใน ⇒ $\sin C > 0$ ⇒ หารสองข้างด้วย $\sin C$ ได้ ⇒ $12 = 18\cos C$ ⇒ $\cos C = \dfrac{2}{3}$',
    r'<b>ขั้นที่ 2:</b> แทนค่านี้ลงกฎโคไซน์หน้าที่มีมุม $C$ คือ $c^{2} = a^{2} + b^{2} - 2ab\cos C$',
    r'⇒ $81 = a^{2} + 144 - 2\left(a\right)\left(12\right)\left(\dfrac{2}{3}\right) = a^{2} + 144 - 16a$ ⇒ $a^{2} - 16a + 63 = 0$ ⇒ $\left(a - 7\right)\left(a - 9\right) = 0$ ⇒ $a = 7$ หรือ $a = 9$',
    r'<b>ขั้นที่ 3:</b> สมการกำลังสองข้างบนสร้างจาก $\cos C = \dfrac{2}{3}$ ล้วน ๆ ยังไม่ได้ใช้ $B = 2C$ จึงต้องเอาทั้งสองรากไปสอบกับ $\cos B = \dfrac{a^{2} + c^{2} - b^{2}}{2ac}$ เทียบค่าเป้า $\cos 2C = 2\cos^{2}C - 1 = 2\left(\dfrac{2}{3}\right)^{2} - 1 = -\dfrac{1}{9}$',
    r'⇒ ทั้ง $B$ และ $2C$ อยู่ระหว่าง $0$ กับ $\pi$ ซึ่งโคไซน์เป็นหนึ่งต่อหนึ่ง การเทียบโคไซน์จึงตัดสินได้เด็ดขาด',
    r'⇒ ราย $a = 9$ ให้ $\cos B = \dfrac{81 + 81 - 144}{2\left(9\right)\left(9\right)} = \dfrac{18}{162} = \dfrac{1}{9} \ne -\dfrac{1}{9}$ ⇒ ตกรอบ',
    r'⇒ ราย $a = 7$ ให้ $\cos B = \dfrac{49 + 81 - 144}{2\left(7\right)\left(9\right)} = \dfrac{-14}{126} = -\dfrac{1}{9}$ ✓ ⇒ ผ่าน ⇒ เหลือรายเดียว ⇒ ความยาวด้าน $a$ เท่ากับ $7$ หน่วย',
]
TIER3_HEAD = r'<b>【 แบบที่ 3 ▸ ⚡ ประยุกต์ · ทฤษฎีบทมุมสองเท่าในสามเหลี่ยม $b^{2} = c(c + a)$ (double-angle triangle theorem) 】</b>'
TIER3 = [
    r'⚡ <b>เหมาะกับ</b> เด็กที่พื้นฐานคณิตดี · จำได้ว่ารูปสามเหลี่ยมที่มีมุมหนึ่งเป็นสองเท่าของอีกมุมหนึ่งมีสูตรลัดผูกความยาวสามด้านไว้ให้แล้ว',
    r'<b>ขั้นที่ 1:</b> ตั้งสูตรลัดจากเงื่อนไข $B = 2C$ · กฎไซน์คู่ $b$ กับ $c$ ให้ $\dfrac{b}{c} = \dfrac{\sin 2C}{\sin C} = 2\cos C$',
    r'⇒ แทน $\cos C = \dfrac{a^{2} + b^{2} - c^{2}}{2ab}$ จากกฎโคไซน์ ⇒ $\dfrac{b}{c} = \dfrac{a^{2} + b^{2} - c^{2}}{ab}$ ⇒ คูณไขว้แล้วจัดรูปได้ $\left(a - c\right)\left[b^{2} - c\left(c + a\right)\right] = 0$',
    r'⇒ สาขา $a = c$ ให้ $A = C$ ⇒ $4C = \pi$ ⇒ $B = \dfrac{\pi}{2}$ ⇒ $b^{2} = a^{2} + c^{2} = 2c^{2} = c\left(c + a\right)$ อยู่ดี ⇒ สรุปเป็นทฤษฎีบทได้ว่า $B = 2C$ ให้ $b^{2} = c\left(c + a\right)$ เสมอ',
    r'<b>ขั้นที่ 2:</b> แทนตัวเลขที่โจทย์ให้ลงสูตรเดียวนี้ โดย $b = 12$ , $c = 9$',
    r'⇒ $144 = 9\left(9 + a\right)$ ⇒ $16 = 9 + a$ ⇒ $a = 7$ หน่วย ⇒ ตรวจย้อนได้ว่า $9\left(9 + 7\right) = 144 = 12^{2}$ ✓',
    r'<b>ข้อต่าง:</b> เงื่อนไข $B = 2C$ ถูกเก็บไว้ครบในตัวสูตร สมการปลายทางจึงเป็นสมการเชิงเส้นที่มีรากเดียว ⇒ ไม่ต้องคำนวณค่า $\cos C$ ออกมาเป็นตัวเลข ไม่ต้องแก้สมการกำลังสอง และไม่มีรากปลอมให้คัดเหมือนแบบที่ 1–2',
]
